-- =============================================================================
-- Migration 006: service_subpackages parent index + seed offer-system catalog
-- =============================================================================

-- Step 1: add missing index on service_subpackages
create index if not exists service_subpackages_parent
  on public.service_subpackages (parent_package_id, sort_order)
  where archived = false;

-- Step 2: upsert service_packages from catalog
