-- Step 4: archive old placeholder packages seeded by migration 024
-- (generic codes: basic/standard/premium/starter/business/enterprise)
-- These are superseded by the catalog-keyed rows above.
update public.service_packages
  set archived = true
  where code in ('basic', 'standard', 'premium', 'starter', 'business', 'enterprise')
    and archived = false;
